<?php
require_once __DIR__.'/../core/security.php'; require_once __DIR__.'/../core/auth.php'; require_once __DIR__.'/../core/rbac.php'; require_once __DIR__.'/../core/csrf.php'; require_once __DIR__.'/../core/store_pairing.php';
start_secure_session(); $me=require_menu_access('settings','view');
if(!current_user_is_owner() && !has_menu_access($me,'settings','edit')){http_response_code(403);exit('Akses ditolak');}
sp_schema(); $notice=''; $error='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST') {
 csrf_check(); $action=(string)($_POST['action']??'');
 try{
  if($action==='generate') { $code=strtoupper(bin2hex(random_bytes(6))); db()->prepare('INSERT INTO store_pairing_codes(code_hash,expires_at) VALUES(?,DATE_ADD(NOW(),INTERVAL 10 MINUTE))')->execute([hash('sha256',$code)]); $_SESSION['store_pairing_display_code']=$code; $notice='Kode pairing berlaku 10 menit dan hanya sekali pakai.'; }
  if($action==='request') {
   $url=sp_url((string)($_POST['url']??'')); if($url===sp_local_url()) throw new RuntimeException('Tidak dapat pairing dengan website sendiri.');
   $secret=pairing_secret(); $code=pairing_request_code('STORE'); $name=substr(trim((string)($_POST['name']??'Toko')),0,180);
   $result=sp_call($url,'api/store-pairing/request.php',['request_code'=>$code,'request_secret_hash'=>password_hash($secret,PASSWORD_DEFAULT),'requester_name'=>sp_label(),'requester_base_url'=>sp_local_url(),'pairing_code'=>trim((string)($_POST['code']??''))]);
   db()->prepare("INSERT INTO api_pairing_requests(direction,request_code,request_secret_hash,requester_name,requester_type,requester_base_url,target_name,target_type,target_base_url,requested_scope,status,local_secret_encrypted,expires_at) VALUES('outgoing',?,? ,?,'adena_store',?,?,'adena_store',?,'store_product_readonly','pending',?,DATE_ADD(NOW(),INTERVAL 48 HOUR))")->execute([$code,password_hash($secret,PASSWORD_DEFAULT),sp_label(),sp_local_url(),$name,$url,pairing_encrypt_secret($secret)]);
   $notice='Permintaan dikirim, menunggu persetujuan toko tujuan.';
  }
  if($action==='approve' || $action==='reject') {
   $id=(int)($_POST['id']??0); $st=db()->prepare("SELECT * FROM api_pairing_requests WHERE id=? AND direction='incoming' AND requester_type='adena_store' AND status='pending'");$st->execute([$id]);$r=$st->fetch(PDO::FETCH_ASSOC); if(!$r)throw new RuntimeException('Permintaan tidak ditemukan / sudah ditangani.');
   if(strtotime($r['expires_at'])<time())throw new RuntimeException('Permintaan kedaluwarsa.');
   if($action==='approve') { $token=pairing_secret(); sp_connect($r['request_code'],$r['requester_name'],$r['requester_base_url'],$token); db()->prepare("UPDATE api_pairing_requests SET status='approved',access_token_encrypted=?,approved_by=?,approved_at=NOW() WHERE id=?")->execute([pairing_encrypt_secret($token),(int)$me['id'],$id]);$notice='Disetujui. Toko peminta perlu klik Periksa Status untuk mengaktifkan katalog dua arah.'; }
   else { db()->prepare("UPDATE api_pairing_requests SET status='rejected',rejected_by=?,rejected_at=NOW() WHERE id=?")->execute([(int)$me['id'],$id]);$notice='Permintaan ditolak.'; }
  }
  if($action==='check') {
   $id=(int)($_POST['id']??0);$st=db()->prepare("SELECT * FROM api_pairing_requests WHERE id=? AND direction='outgoing' AND requester_type='adena_store'");$st->execute([$id]);$r=$st->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('Permintaan tidak ditemukan');
   $secret=pairing_decrypt_secret($r['local_secret_encrypted']);if(!$secret)throw new RuntimeException('Secret pairing tidak tersedia.');
   $response=sp_call($r['target_base_url'],'api/store-pairing/status.php',['request_code'=>$r['request_code'],'request_secret'=>$secret]);
   $status=$response['status']; if(!in_array($status,['pending','approved','rejected','expired'],true))throw new RuntimeException('Status remote tidak valid');
   if($status==='approved') { $token=(string)($response['access_token']??''); if(strlen($token)<40)throw new RuntimeException('Token persetujuan tidak valid');sp_connect($r['request_code'],$r['target_name']?:($response['remote_name']??'Toko'),$r['target_base_url'],$token); }
   db()->prepare('UPDATE api_pairing_requests SET status=?,last_checked_at=NOW() WHERE id=?')->execute([$status,$id]);$notice='Status: '.$status;
  }
  if($action==='revoke') { $id=(int)($_POST['id']??0); $st=db()->prepare("SELECT id FROM api_connections WHERE id=? AND connection_type='store'");$st->execute([$id]);if(!$st->fetchColumn())throw new RuntimeException('Koneksi tidak ditemukan');db()->prepare("UPDATE api_connections SET status='revoked',revoked_at=NOW(),revoked_by=? WHERE id=?")->execute([(int)$me['id'],$id]);db()->prepare("UPDATE api_remote_connections SET is_active=0 WHERE token=?")->execute(['pairing:'.$id]);$notice='Koneksi lokal dinonaktifkan. Toko lain harus menonaktifkan secara terpisah.'; }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$in=db()->query("SELECT * FROM api_pairing_requests WHERE direction='incoming' AND requester_type='adena_store' ORDER BY id DESC LIMIT 80")->fetchAll(PDO::FETCH_ASSOC);
$out=db()->query("SELECT * FROM api_pairing_requests WHERE direction='outgoing' AND requester_type='adena_store' ORDER BY id DESC LIMIT 80")->fetchAll(PDO::FETCH_ASSOC);
$con=db()->query("SELECT * FROM api_connections WHERE connection_type='store' ORDER BY id DESC")->fetchAll(PDO::FETCH_ASSOC);
$code=(string)($_SESSION['store_pairing_display_code']??'');unset($_SESSION['store_pairing_display_code']);
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pairing Antar Toko</title><link rel="stylesheet" href="<?=e(asset_url('assets/app.css'))?>"><style>dialog{border:1px solid #ddd;border-radius:14px;max-width:540px;width:90%;padding:24px}dialog::backdrop{background:#0007}.sp-table{width:100%;border-collapse:collapse}.sp-table td,.sp-table th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.sp-actions{display:flex;gap:8px;flex-wrap:wrap}input{max-width:100%;width:100%;padding:9px;margin:6px 0 14px} .sp-alert{padding:12px;border-radius:8px;background:#d1fae5;margin:12px 0}.sp-error{background:#fee2e2}</style></head><body><div class="container"><?php include __DIR__.'/partials_sidebar.php'; ?><div class="main"><div class="topbar"><button class="btn" type="button" data-toggle-sidebar>Menu</button></div><div class="content"><div class="card"><h2>Pairing Antar Toko</h2><p>Koneksi dua arah untuk membaca katalog produk. Impor produk tetap manual.</p>
<?php if($notice):?><div class="sp-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="sp-alert sp-error"><?=e($error)?></div><?php endif;?>
<div class="sp-actions"><button class="btn" onclick="document.getElementById('add').showModal()">+ Hubungkan Toko</button><button class="btn" onclick="document.getElementById('code').showModal()">Kode Pairing Saya</button><button class="btn" onclick="document.getElementById('incoming').showModal()">Permintaan Masuk (<?=count(array_filter($in,fn($x)=>$x['status']==='pending'))?>)</button><button class="btn" onclick="document.getElementById('history').showModal()">Riwayat</button><a class="btn" href="<?=e(base_url('admin/product_import.php'))?>">Lihat / Impor Katalog</a></div>
<h3>Toko Terhubung</h3><div style="overflow:auto"><table class="sp-table"><thead><tr><th>Toko</th><th>Website</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($con as $c):?><tr><td><?=e($c['connection_name'])?></td><td><?=e($c['remote_base_url'])?></td><td><?=e($c['status'])?></td><td><?php if($c['status']==='active'):?><form method="post" onsubmit="return confirm('Nonaktifkan koneksi lokal?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="revoke"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="btn">Nonaktifkan</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<h3>Permintaan Terkirim</h3><div style="overflow:auto"><table class="sp-table"><tr><th>Toko</th><th>Status</th><th>Aksi</th></tr><?php foreach($out as $r):?><tr><td><?=e($r['target_name']?:$r['target_base_url'])?></td><td><?=e($r['status'])?></td><td><?php if(in_array($r['status'],['pending','approved'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="check"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn">Periksa Status</button></form><?php endif;?></td></tr><?php endforeach;?></table></div>
</div></div></div></div>
<dialog id="add"><h3>Hubungkan Toko</h3><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="request"><label>Nama Toko<input name="name" required maxlength="180"></label><label>URL HTTPS Toko Tujuan<input name="url" placeholder="https://toko.example.com" required></label><label>Kode sementara dari toko tujuan<input name="code" required autocomplete="off"></label><div class="sp-actions"><button class="btn">Kirim Permintaan</button><button class="btn" type="button" onclick="document.getElementById('add').close()">Batal</button></div></form></dialog>
<dialog id="code"><h3>Kode Pairing Toko Ini</h3><p>Berikan kode berikut kepada pengelola toko yang akan meminta pairing. Berlaku 10 menit, sekali pakai.</p><?php if($code):?><p style="font-size:24px;font-weight:bold;letter-spacing:2px"><?=e($code)?></p><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="generate"><button class="btn">Buat Kode Baru</button></form><button class="btn" onclick="document.getElementById('code').close()">Tutup</button></dialog>
<dialog id="incoming"><h3>Permintaan Masuk</h3><?php foreach($in as $r):?><div style="border-bottom:1px solid #ddd;padding:12px 0"><b><?=e($r['requester_name'])?></b><br><?=e($r['requester_base_url'])?> — <?=e($r['status'])?><?php if($r['status']==='pending'):?><div class="sp-actions"><?php foreach(['approve'=>'Setujui','reject'=>'Tolak'] as $a=>$label):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=e($a)?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn"><?=e($label)?></button></form><?php endforeach;?></div><?php endif;?></div><?php endforeach;?><button class="btn" onclick="document.getElementById('incoming').close()">Tutup</button></dialog>
<dialog id="history"><h3>Riwayat Pairing</h3><?php foreach(array_merge($in,$out) as $r):?><p><?=e($r['requester_name'])?> — <?=e($r['request_code'])?> — <?=e($r['status'])?></p><?php endforeach;?><button class="btn" onclick="document.getElementById('history').close()">Tutup</button></dialog>
<script src="<?=e(asset_url('assets/app.js'))?>"></script><?php if($code):?><script>document.getElementById('code').showModal()</script><?php endif;?></body></html>
